return $input.all().map(item => {
  const json = item.json;
  const data = json.body?.data || {};
  const key = data.key || {};

  const remoteJid = key.remoteJid || '';
  const senderPn = key.senderPn || '';
  // [AJUSTE] Adicionada a leitura do remoteJidAlt
  const remoteJidAlt = key.remoteJidAlt || ''; 

  // Limpa os números
  const cleanRemote = remoteJid.replace(/\D/g, '');
  const cleanSender = senderPn.replace(/\D/g, '');
  // [AJUSTE] Limpa o remoteJidAlt
  const cleanRemoteAlt = remoteJidAlt.replace(/\D/g, '');

  let telefoneCorrigido = '';

  // REGRA DE OURO (Atualizada):
  // 1. Tentar usar o senderPn.
  if (cleanSender.length >= 10) {
    telefoneCorrigido = cleanSender;
  } 

  // 2. Tentar usar o remoteJidAlt (caso de LID, como no seu teste).
  // [AJUSTE] Adicionado este bloco else if
  else if (cleanRemoteAlt.length >= 10 && remoteJidAlt.endsWith('@s.whatsapp.net')) {
    telefoneCorrigido = cleanRemoteAlt;
  }

  // 3. Se não houver, checar se o remoteJid é um JID de usuário (DM padrão).
  else if (remoteJid.endsWith('@s.whatsapp.net')) {
    telefoneCorrigido = cleanRemote;
  }

  // 3. Padroniza para E.164 Brasil
  if (telefoneCorrigido && !telefoneCorrigido.startsWith('55')) {
    telefoneCorrigido = '55' + telefoneCorrigido;
  }

  // 4. Sobrescreve o remoteJid SEMPRE com o JID
  if (telefoneCorrigido) {
    key.remoteJid = telefoneCorrigido + '@s.whatsapp.net';
  }

  return {
    json
  };
});

// 0. Captura do telefone
let telefoneContato = "";

try {
    telefoneContato = $('RECEPTIVO').first().json.remoteJid || "";
} catch (e) {
    // Continua vazio caso não encontre o telefone
}

// 1. Captura segura da saída do agente
let rawOutput = "";

if (typeof $json !== "undefined") {
    rawOutput =
        $json.output ??
        $json.text ??
        $json.message ??
        "";
}

// Evita transformar objetos em "[object Object]"
if (typeof rawOutput === "object" && rawOutput !== null) {
    rawOutput = JSON.stringify(rawOutput);
}

let finalResponse = String(rawOutput).trim();

// 2. Limpeza inicial
const thinkingRegex = /<thinking>[\s\S]*?<\/thinking>/gim;

finalResponse = finalResponse
    .replace(thinkingRegex, "")
    .trim();

if (finalResponse.startsWith("===")) {
    finalResponse = finalResponse.substring(3).trim();
}

// 3. Extração segura do JSON
let extractedData = null;

// Monta ``` por ASCII para evitar problemas no n8n
const bt3 = String.fromCharCode(96).repeat(3);

const jsonMarkdownRegex = new RegExp(
    bt3 + "(?:json)?\\s*(\\{[\\s\\S]*\\})\\s*" + bt3,
    "i"
);

const match = finalResponse.match(jsonMarkdownRegex);

if (match) {
    try {
        extractedData = JSON.parse(match[1]);

        finalResponse = finalResponse
            .replace(match[0], "")
            .trim();
    } catch (e) {
        // Mantém o conteúdo original se o JSON for inválido
    }
} else {
    // Busca um possível JSON sem bloco Markdown
    const firstBrace = finalResponse.indexOf("{");
    const lastBrace = finalResponse.lastIndexOf("}");

    if (
        firstBrace !== -1 &&
        lastBrace !== -1 &&
        lastBrace > firstBrace
    ) {
        const possibleJsonString = finalResponse.substring(
            firstBrace,
            lastBrace + 1
        );

        try {
            extractedData = JSON.parse(possibleJsonString);

            finalResponse = finalResponse
                .replace(possibleJsonString, "")
                .trim();

            const residualMarkdownRegex = new RegExp(
                bt3 + "json|" + bt3,
                "gi"
            );

            finalResponse = finalResponse
                .replace(residualMarkdownRegex, "")
                .trim();
        } catch (e) {
            // Mantém o conteúdo como texto se não for JSON válido
        }
    }
}

// 4. Se o agente retornou {"message":"..."}, usa essa mensagem
if (
    finalResponse.length === 0 &&
    extractedData &&
    typeof extractedData.message === "string"
) {
    finalResponse = extractedData.message.trim();
}

// Também aceita o campo "mensagem"
if (
    finalResponse.length === 0 &&
    extractedData &&
    typeof extractedData.mensagem === "string"
) {
    finalResponse = extractedData.mensagem.trim();
}

// 5. Divisão de mensagens
const partes = [];

if (finalResponse.length > 0) {
    // Também captura textos sem pontuação no final
    const frases =
        finalResponse.match(/[^.!?]+(?:[.!?]+|$)/g) ||
        [finalResponse];

    let buffer = "";

    for (const frase of frases) {
        const fraseLimpa = frase.trim();

        if (!fraseLimpa) continue;

        const proximoBuffer = buffer
            ? `${buffer} ${fraseLimpa}`
            : fraseLimpa;

        if (proximoBuffer.length > 800) {
            if (buffer.trim()) {
                partes.push(buffer.trim());
            }

            buffer = fraseLimpa;
        } else {
            buffer = proximoBuffer;
        }
    }

    if (buffer.trim()) {
        partes.push(buffer.trim());
    }
}

// 6. Define o status sem forçar conclusão
const statusTriagem =
    extractedData?.status_triagem ||
    "andamento";
const temperaturaLead = extractedData?.temperatura_lead || "MORNO";
const justificativaTemp = extractedData?.justificativa_temperatura || "";
const proximaAcao = extractedData?.proxima_acao_recomendada || "";

// 7. Retorno quando não houver mensagem
if (partes.length === 0) {
    return [
        {
            json: {
                message: "",
                telefone: telefoneContato,
                extracted_data: extractedData,
                status_triagem: statusTriagem,
                temperatura_lead: temperaturaLead,
                justificativa_temperatura: justificativaTemp,
                proxima_acao_recomendada: proximaAcao
            }
        }
    ];
}

// 8. Retorno das mensagens
return partes.map((msg, index) => {
    const isLastMessage = index === partes.length - 1;

    return {
        json: {
            message: msg,
            telefone: telefoneContato,
            extracted_data: isLastMessage
                ? extractedData
                : null,
            status_triagem: isLastMessage
                ? statusTriagem
                : "andamento"
        }
    };
});

