function safe(fn, fallback = "") {
    try {
        const value = fn();
        return value ?? fallback;
    } catch (e) {
        return fallback;
    }
}

// Função para normalizar celular brasileiro (DDD + Nono Dígito)
function normalizarTelefoneBR(numeroRaw) {
    let limpo = String(numeroRaw || "").replace(/\D/g, "");

    if (!limpo.startsWith("55") && (limpo.length === 10 || limpo.length === 11)) {
        limpo = "55" + limpo;
    }

    let comNono = limpo;
    let semNono = limpo;

    if (limpo.startsWith("55")) {
        const ddi = limpo.slice(0, 2);
        const ddd = limpo.slice(2, 4);
        const resto = limpo.slice(4);

        // Se tem 12 dígitos (55 + DDD 2 dígitos + 8 dígitos de celular)
        if (limpo.length === 12 && parseInt(ddd, 10) >= 11) {
            semNono = limpo;
            comNono = `${ddi}${ddd}9${resto}`; // Adiciona o 9º dígito
        } 
        // Se tem 13 dígitos (55 + DDD 2 dígitos + 9 dígitos)
        else if (limpo.length === 13 && parseInt(ddd, 10) >= 11) {
            comNono = limpo;
            if (resto.startsWith("9")) {
                semNono = `${ddi}${ddd}${resto.slice(1)}`; // Remove o 9º dígito para busca
            }
        }
    }

    return {
        comNono,                             // Ex: 5519991859143 (Padrão oficial para SALVAR no Bitrix)
        semNono,                             // Ex: 551991859143 (Usado para BUSCAR no Bitrix)
        comNonoSemDDI: comNono.slice(2),     // Ex: 19991859143
        semNonoSemDDI: semNono.slice(2)      // Ex: 1991859143
    };
}

