            // Contato principal SEMPRE com o 9º dígito para criar no Bitrix sem duplicar
            Contato: fPhone.comNono,               
            ContatoSemDDI: fPhone.comNonoSemDDI,   

            // Variações completas para consulta de duplicados
            ContatoSemNono: fPhone.semNono,        
            ContatoSemNonoSemDDI: fPhone.semNonoSemDDI, 

            ContatoRecusado: contatoEhRecusado,
            WhatsAppJid: safe(() => $('RECEPTIVO').first().json.remoteJid, telefoneRaw),
            MensagemFinal: $json.message || "",
            StatusTriagem: statusTriagem,
            Temperatura: String(temperatura).toUpperCase(),
            BadgeTemperatura: badgeTemperatura,
            JustificativaTemperatura: justificativaTemp,
            ProximaAcaoRecomendada: proximaAcao,
            ResponsavelHomologacaoId: RESPONSAVEL_HOMOLOGACAO_ID,
            CategoriaBitrix: CATEGORY_PADRAO,
            StageDestino: STAGE_PADRAO,
            extracted_data: data
        }
    }
];

