const result = $input.item.json.result || {};
const dadosLead = $('1. Preparar Dados Lead').first().json;

let contactIds = [];

if (result.CONTACT && Array.isArray(result.CONTACT)) {
    contactIds = result.CONTACT;
} else if (Array.isArray(result)) {
    contactIds = result.map(c => c.ID || c.id).filter(Boolean);
}

contactIds = contactIds.map(String);

if (!contactIds.length) {
    return [{ json: { ...dadosLead, contactIds: [], testContactId: "", temContatos: false } }];
}

// Retorna 1 item no n8n para cada ID de contato encontrado
return contactIds.map(id => ({
    json: {
        ...dadosLead,
        testContactId: id,
        allContactIds: contactIds,
        temContatos: true
    }
}));

const httpResponses = $input.all();
const inputItems = $('Desmembrar IDs para Consulta').all();
const dadosLead = $('1. Preparar Dados Lead').first().json;

const allContactIds = (inputItems[0] && inputItems[0].json.allContactIds) 
    ? inputItems[0].json.allContactIds.map(String) 
    : [];

const CONECTOR_NOVO = "ffwhats_connector";

let bestContactId = null;
let maxTimestamp = -1;
let maxChatId = -1;
let bestActiveFound = false;

// Varre TODOS os contatos e TODOS os chats para encontrar a conversa com o MAIOR TIMESTAMP DE ATIVIDADE RECENTE
for (let i = 0; i < httpResponses.length; i++) {
    const res = httpResponses[i].json ? httpResponses[i].json.result : null;
    const currentTestId = String((inputItems[i] && inputItems[i].json.testContactId) || "");

    if (res && Array.isArray(res)) {
        for (let chat of res) {
            const userCode = String(chat.USER_CODE || chat.ITEM_ID || "");
            const isActive = String(chat.ACTIVE || "").toUpperCase() === "Y";

            // Aceita o conector novo ffwhats_connector ou conectores imol
            if (userCode.includes(CONECTOR_NOVO) || userCode.includes("imol|")) {
                // Extrai a data da última mensagem / modificação do chat
                const dateStr = chat.DATE_MODIFY || chat.LAST_MESSAGE_DATE || chat.DATE_CREATE || "";
                const currentTimestamp = dateStr ? new Date(dateStr).getTime() : 0;
                const currentChatId = Number(chat.CHAT_ID || chat.ID || 0);

                // Regra de Ouro:
                // 1. Priorizar chats com ACTIVE = Y (abertos hoje)
                // 2. Comparar pelo maior Timestamp de atividade recente (DATE_MODIFY)
                // 3. Desempate: Maior CHAT_ID numérico
                if (isActive && !bestActiveFound) {
                    bestActiveFound = true;
                    maxTimestamp = currentTimestamp;
                    maxChatId = currentChatId;
                    bestContactId = currentTestId;
                } else if (isActive === bestActiveFound) {
                    if (currentTimestamp > maxTimestamp) {
                        maxTimestamp = currentTimestamp;
                        maxChatId = currentChatId;
                        bestContactId = currentTestId;
                    } else if (currentTimestamp === maxTimestamp && currentChatId > maxChatId) {
                        maxChatId = currentChatId;
                        bestContactId = currentTestId;
                    }
                }
            }
        }
    }
}

// Fallback: Se nenhum chat for encontrado, seleciona o ID de contato MAIS RECENTE (maior ID de contato)
const contactIdSalvo = bestContactId || String(
    allContactIds.map(Number).sort((a, b) => b - a)[0] || ""
);

// Ordena a lista colocando o ID principal MANTIDO como o PRIMEIRO elemento (Requisito do crm.entity.mergeBatch do Bitrix)
const orderedContactIds = [contactIdSalvo, ...allContactIds.filter(id => String(id) !== String(contactIdSalvo))];
const contatosParaDeletar = allContactIds.filter(id => String(id) !== String(contactIdSalvo));

return [{
    json: {
        ...dadosLead,
        contactIds: orderedContactIds,
        contactId: contactIdSalvo,              // ID MANTIDO: Contato com o Chat MAIS RECENTE e ATIVO de hoje
        contatosDuplicados: contatosParaDeletar, // IDs duplicados a serem mesclados
        temDuplicados: orderedContactIds.length > 1
    }
}];

