const isolarData = $('Garantir Contato com Chat na Linha').first().json;
const ids = isolarData.contactIds || [];

const baseUrl = "https://b24-88dbfb.bitrix24.com.br/rest/244936/1jw82ol2jaf0ivve/crm.deal.list.json";

// Busca GLOBAL: Seleciona cards em QUALQUER categoria/funil vinculados ao cliente
const params = {
    "select[0]": "ID",
    "select[1]": "TITLE",
    "select[2]": "STAGE_ID",
    "select[3]": "CATEGORY_ID",
    "select[4]": "STAGE_SEMANTIC_ID",
    "order[ID]": "DESC"
};

if (!ids.length) {
    params["filter[ID]"] = 0;
} else {
    // Procura cards vinculados a qualquer ID de contato do cliente
    ids.forEach((id, index) => {
        params[`filter[CONTACT_ID][${index}]`] = id;
    });
}

const queryString = Object.entries(params)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join("&");

return [
    {
        json: {
            ...isolarData,
            finalUrl: `${baseUrl}?${queryString}`
        }
    }
];

const item = items[0];
const inputData = item.json;

// --- CAPTURA ROBUSTA DO CONTACT_ID EM QUALQUER CAMINHO ---
let contactId = "";

const possiveisNois = [
    "Garantir Contato com Chat na Linha",
    "Normalizar contato",
    "Isolar IDs dos Contatos",
    "1. Preparar Dados Lead"
];

for (const nomeNo of possiveisNois) {
    try {
        const nodeData = $(nomeNo).first()?.json;
        if (nodeData) {
            if (nodeData.contactId && String(nodeData.contactId).trim() !== "" && String(nodeData.contactId) !== "NÃO ENCONTRADO") {
                contactId = String(nodeData.contactId).trim();
                break;
            }
            if (Array.isArray(nodeData.contactIds) && nodeData.contactIds[0] && String(nodeData.contactIds[0]) !== "NÃO ENCONTRADO") {
                contactId = String(nodeData.contactIds[0]).trim();
                break;
            }
        }
    } catch (e) {
        // Ignora nós que não rodaram no caminho atual
    }
}

if (!contactId && inputData.contactId) {
    contactId = String(inputData.contactId).trim();
}

contactId = contactId ? contactId.replace(/\s/g, '') : "";

// --- DADOS DO LEAD ---
const dadosLead = $('1. Preparar Dados Lead').first().json;

const nome = dadosLead.Nome || "Cliente Mundial Motos";
const cidade = dadosLead.Cidade || "";
const setor = dadosLead.Setor || "Outros/Geral";
const modelo = dadosLead.Modelo || "";
const tipoAtendimento = dadosLead.TipoAtendimento || "";
const resumo = dadosLead.Resumo || "";
const contato = dadosLead.Contato || "";
const categoriaBitrix = dadosLead.CategoriaBitrix || 18;
const stageDestino = dadosLead.StageDestino || "C18:NEW";
const entrada = dadosLead.Entrada || "";
const parcelaIdeal = dadosLead.ParcelaIdeal || "";
const melhorHorario = dadosLead.MelhorHorarioRetorno || "";
const contatoRecusado = dadosLead.ContatoRecusado || false;

const titulo = `[WhatsApp] ${setor} | ${nome}${modelo ? " | " + modelo : ""}`;

// --- TEXTO PARA O TIMELINE (HTML) ---
const contatoDisplay = contatoRecusado
    ? `${contato} <i>(cliente recusou confirmar — número obtido via WhatsApp)</i>`
    : contato;

const horarioLinha = melhorHorario
    ? `<b>Melhor horário de retorno:</b> ${melhorHorario}<br>`
    : "";

const comentarioHtml = `
<b>🏍️ Novo atendimento qualificado pelo SDR IA - Mundial Motos</b><br><br>
<b>Classificação / Feeling:</b> ${dadosLead.BadgeTemperatura || "🟡 LEAD MORNO"}<br>
${dadosLead.JustificativaTemperatura ? "<b>Motivo do Score:</b> " + dadosLead.JustificativaTemperatura + "<br>" : ""}
${dadosLead.ProximaAcaoRecomendada ? "<b>🎯 Próxima Ação Recomendada:</b> <u>" + dadosLead.ProximaAcaoRecomendada + "</u><br>" : ""}
<br>
<b>Nome:</b> ${nome}<br>
<b>Telefone/WhatsApp:</b> ${contatoDisplay}<br>
<b>Cidade/Unidade:</b> ${cidade || "Não informado"}<br>
<b>Setor:</b> ${setor}<br>
<b>Tipo de atendimento:</b> ${tipoAtendimento || "Não informado"}<br>
<b>Modelo:</b> ${modelo || "Não informado"}<br>
${horarioLinha}
<b>Resumo:</b> ${resumo || "Não informado"}<br><br>
Vínculo do Contato: <b>${contactId ? "ID Bitrix #" + contactId : "SEM VÍNCULO"}</b>
`.trim();

// --- TEXTO PLANO ---
const comentarioTexto = comentarioHtml
    .replace(/<br>/g, "\n")
    .replace(/<\/?[^>]+>/g, "");

// --- RESUMO ESTRUTURADO ---
const resumoLinhas = [
    `Nome: ${nome}`,
    `Telefone/WhatsApp: ${contato}${contatoRecusado ? " (não confirmed pelo cliente)" : ""}`,
    `Cidade/Unidade: ${cidade || "Não informado"}`,
    `Setor: ${setor}`,
    `Tipo de atendimento: ${tipoAtendimento || "Não informado"}`,
    `Modelo: ${modelo || "Não informado"}`,
    `Entrada: ${entrada || "Não informado"}`,
    `Parcela ideal: ${parcelaIdeal || "Não informado"}`
];

if (melhorHorario) {
    resumoLinhas.push(`Melhor horário de retorno: ${melhorHorario}`);
}

if (dadosLead.BadgeTemperatura) resumoLinhas.push(`Classificação: ${dadosLead.BadgeTemperatura}`);
if (dadosLead.ProximaAcaoRecomendada) resumoLinhas.push(`Próxima Ação Recomendada: ${dadosLead.ProximaAcaoRecomendada}`);
resumoLinhas.push(`Resumo: ${resumo || "Não informado"}`);
const resumoFormulario = resumoLinhas.join("\n");

// --- PAYLOAD DO DEAL ---
const fields = {
    TITLE: titulo,
    CATEGORY_ID: Number(categoriaBitrix),
    STAGE_ID: stageDestino,
    SOURCE_ID: "WEB",
    SOURCE_DESCRIPTION: "WhatsApp - SDR IA Mundial Motos",
    COMMENTS: comentarioTexto,
    ASSIGNED_BY_ID: 32598 // Atribuição oficial ao Eduardo Alaminos (Homologação)
};

if (contactId && !isNaN(Number(contactId))) {
    fields.CONTACT_ID = Number(contactId);
}

// CAMPOS PERSONALIZADOS (UF_CRM)
const UF = {
    CIDADE: "UF_CRM_1722019521471",
    MODELO: "UF_CRM_1722450820175",
    TIPO_ATENDIMENTO: "UF_CRM_1703613635957",
    RESUMO: "UF_CRM_1784036238",
    ENTRADA: "UF_CRM_1755352071",
    PARCELA_IDEAL: "UF_CRM_1731162275"
};

if (UF.CIDADE && cidade) fields[UF.CIDADE] = cidade;
if (UF.MODELO && modelo) fields[UF.MODELO] = modelo;
if (UF.TIPO_ATENDIMENTO && tipoAtendimento) fields[UF.TIPO_ATENDIMENTO] = tipoAtendimento;
if (UF.RESUMO) fields[UF.RESUMO] = resumoFormulario;
if (UF.ENTRADA && String(entrada).trim()) fields[UF.ENTRADA] = entrada;
if (UF.PARCELA_IDEAL && String(parcelaIdeal).trim()) fields[UF.PARCELA_IDEAL] = parcelaIdeal;

item.json.bitrix_body_create = { fields };
item.json.novo_comentario = comentarioHtml;
item.json.contactId_usado = contactId || "";
item.json.deal_id_created = true;

return items;

